//! Writes the models in `src/model/` and the table list in
//! `src/tables/list.rs` from `schema/` and `schema/settings.toml`.

use crate::schema::{self, Field, LANGUAGES, Shape, Tables};
use crate::settings::{self, FieldSettings, Raw, Settings, StructSettings};
use anyhow::{Context, bail};
use std::collections::{BTreeMap, BTreeSet};
use std::fmt::Write as _;
use std::fs;
use std::io::Write as _;
use std::path::Path;
use std::process::{Command, ExitCode, Stdio};

/// The first line of every generated file.
pub const MARKER: &str = "// @generated by `cargo xtask models` from `schema/`. Do not edit.";

/// What every generated struct derives.
const DERIVES: [&str; 4] = ["Debug", "Clone", "PartialEq", "Deserialize"];

/// Whether to write the generated files, or only report the ones that differ.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Mode {
    /// Write files that differ.
    Write,
    /// Report files that differ, and fail if any do.
    Check,
}

/// Generate the files and write or check them.
pub fn run(root: &Path, mode: Mode) -> anyhow::Result<ExitCode> {
    let tables = schema::read(&root.join("schema"))?;
    let settings = settings::read(&root.join("schema/settings.toml"))?;
    let files = generate(&tables, &settings)?;
    let mut stale = Vec::new();
    for (path, code) in &files {
        let code = rustfmt(code).with_context(|| format!("cannot format {path}"))?;
        let full = root.join(path);
        if let Some(parent) = full.parent() {
            fs::create_dir_all(parent)
                .with_context(|| format!("cannot create {}", parent.display()))?;
        }
        if fs::read_to_string(&full).ok().as_deref() == Some(code.as_str()) {
            continue;
        }
        match mode {
            Mode::Write => {
                fs::write(&full, &code).with_context(|| format!("cannot write {path}"))?;
                println!("wrote {path}");
            }
            Mode::Check => stale.push(path.clone()),
        }
    }
    // Generated files that are no longer generated.
    let model = root.join("src/model");
    for entry in fs::read_dir(&model).with_context(|| format!("cannot read {}", model.display()))? {
        let path = entry?.path();
        let name = path
            .file_name()
            .and_then(|n| n.to_str())
            .unwrap_or_default();
        let relative = format!("src/model/{name}");
        let generated = fs::read_to_string(&path).is_ok_and(|text| text.starts_with(MARKER));
        if files.contains_key(&relative) || !generated {
            continue;
        }
        match mode {
            Mode::Write => {
                fs::remove_file(&path).with_context(|| format!("cannot remove {relative}"))?;
                println!("removed {relative}");
            }
            Mode::Check => stale.push(relative),
        }
    }
    if stale.is_empty() {
        return Ok(ExitCode::SUCCESS);
    }
    eprintln!("these files are out of date; run `cargo xtask models`:");
    for path in stale {
        eprintln!("  {path}");
    }
    Ok(ExitCode::FAILURE)
}

/// Format Rust code with `rustfmt`.
fn rustfmt(code: &str) -> anyhow::Result<String> {
    let mut child = Command::new("rustfmt")
        .args(["--edition", "2024", "--emit", "stdout"])
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .context("cannot run rustfmt")?;
    child
        .stdin
        .take()
        .context("rustfmt has no standard input")?
        .write_all(code.as_bytes())
        .context("cannot write to rustfmt")?;
    let output = child.wait_with_output().context("rustfmt did not finish")?;
    if !output.status.success() {
        bail!("{}", String::from_utf8_lossy(&output.stderr));
    }
    String::from_utf8(output.stdout).context("rustfmt wrote invalid UTF-8")
}

/// The generated files before formatting, by path from the repository root.
///
/// # Errors
///
/// Fails when the schema and the settings do not fit together: a table
/// without a struct, a nested object without a struct name, a settings entry
/// for a field the schema does not have, or a struct nothing uses.
pub fn generate(tables: &Tables, settings: &Settings) -> anyhow::Result<BTreeMap<String, String>> {
    Generator::new(tables, settings)?.files()
}

/// What a module's code uses, so it imports only that.
#[derive(Debug, Default)]
struct Uses {
    de: bool,
    map: bool,
    value: bool,
    /// The names in the module's field types, such as `Vec` and `TypeId`.
    types: BTreeSet<String>,
}

/// Names in field types that need no import.
const PRELUDE: [&str; 16] = [
    "BTreeMap", "Option", "String", "Value", "Vec", "bool", "f32", "f64", "i8", "i16", "i32",
    "i64", "u8", "u16", "u32", "u64",
];

/// One generated field.
#[derive(Debug)]
struct GenField {
    doc: Option<String>,
    name: String,
    ty: String,
    rename: Option<String>,
    default: bool,
    with: Option<&'static str>,
}

impl GenField {
    /// The contents of the field's `#[serde(...)]`, if it needs one.
    fn serde(&self) -> Option<String> {
        let mut parts = Vec::new();
        if self.default {
            parts.push("default".to_owned());
        }
        if let Some(json) = &self.rename {
            parts.push(format!("rename = \"{json}\""));
        }
        if let Some(with) = self.with {
            parts.push(format!("deserialize_with = \"{with}\""));
        }
        (!parts.is_empty()).then(|| parts.join(", "))
    }
}

struct Generator<'a> {
    settings: &'a Settings,
    /// Each table's record struct, by file stem.
    records: BTreeMap<&'a str, &'a str>,
    /// The fields of every generated struct, merged from every place it is
    /// used.
    shapes: BTreeMap<&'a str, BTreeMap<String, Field>>,
}

impl<'a> Generator<'a> {
    fn new(tables: &'a Tables, settings: &'a Settings) -> anyhow::Result<Self> {
        let mut records = BTreeMap::new();
        for (name, s) in &settings.structs {
            let Some(file) = &s.file else {
                continue;
            };
            let stem = file
                .strip_suffix(".jsonl")
                .with_context(|| format!("the `file` of `{name}` must end in `.jsonl`"))?;
            if !tables.contains_key(stem) {
                bail!("`{name}` reads `{file}`, which the schema does not have");
            }
            records.insert(stem, name.as_str());
        }
        let missing: Vec<&str> = tables
            .keys()
            .map(String::as_str)
            .filter(|stem| !records.contains_key(stem))
            .collect();
        if !missing.is_empty() {
            bail!(
                "these tables have no struct in the settings: {}",
                missing.join(", ")
            );
        }

        let mut record_shapes = BTreeMap::new();
        for (stem, name) in &records {
            let Shape::Object(fields) = &tables[*stem].record else {
                bail!("the records of `{stem}` are not objects");
            };
            record_shapes.insert(*name, fields.clone());
        }

        // A struct's fields depend on every field that holds it, and those
        // can be in other generated structs, so repeat until nothing changes.
        let mut shapes = record_shapes.clone();
        for _ in 0..64 {
            let mut next = record_shapes.clone();
            for (name, fields) in &shapes {
                for (json, field) in fields {
                    let fs = field_settings(settings, name, json);
                    let Some(object) = object_of(&field.shape, fs) else {
                        continue;
                    };
                    let child = fs.ty.as_deref().with_context(|| {
                        format!("set the `type` of `{name}.{json}` to the struct that holds it")
                    })?;
                    let child = settings.structs.get_key_value(child).with_context(|| {
                        format!("`{name}.{json}` is a `{child}`, which the settings do not declare")
                    })?;
                    if child.1.file.is_some() {
                        bail!("`{name}.{json}` holds a table's record `{}`", child.0);
                    }
                    match next.get_mut(child.0.as_str()) {
                        Some(fields) => merge_fields(fields, object)
                            .with_context(|| format!("in `{}`", child.0))?,
                        None => {
                            next.insert(child.0.as_str(), object.clone());
                        }
                    }
                }
            }
            if next == shapes {
                add_missing_fields(settings, &mut shapes)?;
                let generator = Generator {
                    settings,
                    records,
                    shapes,
                };
                generator.check_settings()?;
                return Ok(generator);
            }
            shapes = next;
        }
        bail!("the structs hold each other in a loop")
    }

    /// Every struct the settings declare is used, and every field they name
    /// exists.
    fn check_settings(&self) -> anyhow::Result<()> {
        for (name, s) in &self.settings.structs {
            let Some(fields) = self.shapes.get(name.as_str()) else {
                bail!("`{name}` is declared in the settings, but no field holds it");
            };
            for json in s.fields.keys() {
                if !fields.contains_key(json) {
                    bail!("the settings name `{name}.{json}`, which the schema does not have");
                }
            }
        }
        Ok(())
    }

    fn files(&self) -> anyhow::Result<BTreeMap<String, String>> {
        let mut records: Vec<(&str, &str)> = self
            .records
            .values()
            .map(|name| {
                let file = self.settings.structs[*name]
                    .file
                    .as_deref()
                    .unwrap_or_default();
                (file, *name)
            })
            .collect();
        records.sort_unstable();
        let mut placed = BTreeSet::new();
        let mut modules: BTreeMap<&str, Vec<&str>> = BTreeMap::new();
        for (_, name) in records {
            self.place(name, &mut placed, &mut modules)?;
        }

        let mut files = BTreeMap::new();
        for (module, names) in modules {
            let mut uses = Uses::default();
            let mut body = String::new();
            for name in &names {
                body.push_str(&self.struct_code(name, &mut uses)?);
                body.push('\n');
            }
            let mut code = format!("{MARKER}\n");
            let doc = self
                .settings
                .modules
                .get(module)
                .and_then(|m| m.doc.as_deref());
            push_doc(&mut code, doc, "//!", "");
            code.push('\n');
            code.push_str(&self.imports(&names, &uses)?);
            code.push('\n');
            code.push_str(&body);
            files.insert(format!("src/model/{module}.rs"), code);
        }
        files.insert("src/tables/list.rs".to_owned(), self.table_list()?);
        Ok(files)
    }

    /// The `use` lines of a model module that defines `structs`: the structs
    /// of other modules from `super`, which re-exports them, the ID types
    /// from `crate::ids`, and whatever else the code uses.
    fn imports(&self, structs: &[&str], uses: &Uses) -> anyhow::Result<String> {
        let mut models = Vec::new();
        let mut ids = Vec::new();
        for name in &uses.types {
            let name = name.as_str();
            if structs.contains(&name) || PRELUDE.contains(&name) {
                continue;
            }
            if self.settings.structs.contains_key(name) {
                models.push(name);
            } else if name.ends_with("Id") {
                ids.push(name);
            } else {
                bail!("unknown type `{name}`: declare it in `[structs]`, or use an ID type");
            }
        }
        let mut code = use_line("super", &models);
        if uses.de {
            code.push_str("use crate::de;\n");
        }
        code.push_str(&use_line("crate::ids", &ids));
        code.push_str("use serde::Deserialize;\n");
        if uses.value {
            code.push_str("use serde_json::Value;\n");
        }
        if uses.map {
            code.push_str("use std::collections::BTreeMap;\n");
        }
        Ok(code)
    }

    /// Put a struct in its module's list, then the structs it holds.
    fn place(
        &self,
        name: &'a str,
        placed: &mut BTreeSet<&'a str>,
        modules: &mut BTreeMap<&'a str, Vec<&'a str>>,
    ) -> anyhow::Result<()> {
        if !placed.insert(name) {
            return Ok(());
        }
        let s = &self.settings.structs[name];
        let module = s
            .module
            .as_deref()
            .with_context(|| format!("set the `module` of `{name}`"))?;
        modules.entry(module).or_default().push(name);
        for (json, field) in &self.shapes[name] {
            let fs = field_settings(self.settings, name, json);
            if object_of(&field.shape, fs).is_none() {
                continue;
            }
            let Some((child, _)) = fs
                .ty
                .as_deref()
                .and_then(|ty| self.settings.structs.get_key_value(ty))
            else {
                continue;
            };
            self.place(child, placed, modules)?;
        }
        Ok(())
    }

    fn struct_code(&self, name: &str, uses: &mut Uses) -> anyhow::Result<String> {
        let s = &self.settings.structs[name];
        let mut code = String::new();
        push_doc(&mut code, s.doc.as_deref(), "///", "");
        let mut derives: Vec<&str> = DERIVES.to_vec();
        derives.extend(s.derive.iter().map(String::as_str));
        writeln!(code, "#[derive({})]", derives.join(", "))?;
        writeln!(code, "#[non_exhaustive]")?;
        writeln!(code, "pub struct {name} {{")?;
        for field in self.fields(name, s)? {
            uses.de |= field.with.is_some();
            uses.map |= field.ty.starts_with("BTreeMap<");
            uses.value |= field.ty == "Value" || field.ty.contains("<Value>");
            uses.types.extend(type_names(&field.ty).map(str::to_owned));
            push_doc(&mut code, field.doc.as_deref(), "///", "    ");
            if let Some(serde) = field.serde() {
                writeln!(code, "    #[serde({serde})]")?;
            }
            writeln!(code, "    pub {}: {},", field.name, field.ty)?;
        }
        writeln!(code, "}}")?;
        if let Some(file) = &s.file {
            match s.key.as_deref() {
                None => writeln!(code, "record!({name}, \"{file}\");")?,
                Some(key) => writeln!(code, "record!({name}, \"{file}\", {key});")?,
            }
        }
        Ok(code)
    }

    fn fields(&self, name: &str, s: &StructSettings) -> anyhow::Result<Vec<GenField>> {
        let is_record = s.file.is_some();
        let mut fields = Vec::new();
        for (json, field) in &self.shapes[name] {
            let fs = field_settings(self.settings, name, json);
            let rust = match (&fs.name, json.as_str()) {
                (Some(rust), _) => rust.clone(),
                (None, "_key") if is_record => "id".to_owned(),
                (None, "_key" | "_value") => {
                    bail!("set the `name` of `{name}.{json}` in the settings")
                }
                (None, _) => snake_case(json),
            };
            let mut generated = GenField {
                doc: fs.doc.clone(),
                rename: (rust != *json).then(|| json.clone()),
                name: rust,
                ty: String::new(),
                default: false,
                with: None,
            };
            generated.ty = if is_record && json == "_key" {
                key_type(name, s, field)?
            } else {
                self.field_type(name, json, field, fs, &mut generated)?
            };
            fields.push(generated);
        }
        Ok(fields)
    }

    fn field_type(
        &self,
        name: &str,
        json: &str,
        field: &Field,
        fs: &FieldSettings,
        out: &mut GenField,
    ) -> anyhow::Result<String> {
        let required = field.required && !fs.optional;
        match (fs.raw, &field.shape) {
            (Some(Raw::Value), _) => Ok(option(required, "Value")),
            (Some(Raw::Items), Shape::Array(_)) => {
                out.default = true;
                Ok("Vec<Value>".to_owned())
            }
            (Some(Raw::Items), _) => {
                bail!("`{name}.{json}` is not a list, so it cannot be `raw = \"items\"`")
            }
            (None, Shape::Text) if required => {
                out.with = Some("de::en");
                Ok("String".to_owned())
            }
            (None, Shape::Text) => {
                out.default = true;
                out.with = Some("de::en_opt");
                Ok("Option<String>".to_owned())
            }
            (None, Shape::Array(item)) => {
                out.default = true;
                self.list_type(name, json, item, fs, out)
            }
            (None, shape) => {
                let ty = match shape {
                    Shape::Object(_) => struct_name(name, json, fs)?,
                    scalar => self.scalar(name, json, scalar, fs)?,
                };
                if fs.default {
                    out.default = true;
                    Ok(ty)
                } else {
                    Ok(option(required, &ty))
                }
            }
        }
    }

    fn list_type(
        &self,
        name: &str,
        json: &str,
        item: &Shape,
        fs: &FieldSettings,
        out: &mut GenField,
    ) -> anyhow::Result<String> {
        match item {
            Shape::Object(fields) if is_map(fields) => {
                out.with = Some("de::kv_map");
                let key = match (&fs.key, &fields["_key"].shape) {
                    (Some(key), _) => key.clone(),
                    (None, Shape::Integer) => "u32".to_owned(),
                    (None, Shape::String) => "String".to_owned(),
                    (None, _) => bail!("set the `key` of `{name}.{json}`"),
                };
                let value = match &fields["_value"].shape {
                    Shape::Object(_) => struct_name(name, json, fs)?,
                    Shape::Array(inner) => match inner.as_ref() {
                        Shape::Object(_) => format!("Vec<{}>", struct_name(name, json, fs)?),
                        Shape::Array(_) | Shape::Text => {
                            bail!("`{name}.{json}` holds a kind of list that is not supported")
                        }
                        scalar => format!("Vec<{}>", self.scalar(name, "_value", scalar, fs)?),
                    },
                    Shape::Text => bail!("`{name}.{json}` maps to text, which is not supported"),
                    scalar => self.scalar(name, "_value", scalar, fs)?,
                };
                Ok(format!("BTreeMap<{key}, {value}>"))
            }
            Shape::Object(fields) if is_keyed_text(fields) => {
                out.with = Some("de::keyed_en");
                Ok("BTreeMap<String, String>".to_owned())
            }
            Shape::Object(_) => Ok(format!("Vec<{}>", struct_name(name, json, fs)?)),
            Shape::Array(_) | Shape::Text => {
                bail!("`{name}.{json}` holds a kind of list that is not supported")
            }
            scalar => Ok(format!("Vec<{}>", self.scalar(name, json, scalar, fs)?)),
        }
    }

    /// The Rust type of a number, flag or string.
    fn scalar(
        &self,
        name: &str,
        json: &str,
        shape: &Shape,
        fs: &FieldSettings,
    ) -> anyhow::Result<String> {
        if let Some(ty) = &fs.ty {
            return Ok(ty.clone());
        }
        match shape {
            Shape::Integer => Ok(match self.settings.ids.get(json) {
                Some(id) => id.clone(),
                None if json == "_key" || json.ends_with("ID") || json.ends_with("IDs") => {
                    "u32".to_owned()
                }
                None => "i64".to_owned(),
            }),
            Shape::Float => Ok("f64".to_owned()),
            Shape::Bool => Ok("bool".to_owned()),
            Shape::String => Ok("String".to_owned()),
            Shape::Unknown => {
                bail!("set the `type` of `{name}.{json}`: only empty lists were seen")
            }
            Shape::Text | Shape::Array(_) | Shape::Object(_) => {
                bail!("`{name}.{json}` is not a number, flag or string")
            }
        }
    }

    fn table_list(&self) -> anyhow::Result<String> {
        let mut rows: Vec<(String, &str)> = self
            .records
            .iter()
            .map(|(stem, name)| {
                let table = self.settings.structs[*name]
                    .table
                    .clone()
                    .unwrap_or_else(|| snake_case(stem));
                (table, *name)
            })
            .collect();
        rows.sort_unstable();
        let mut models: Vec<&str> = rows.iter().map(|(_, name)| *name).collect();
        models.sort_unstable();
        let mut code = format!(
            "{MARKER}\n//! Every table, generated from `schema/`.\n\n\
             use super::{{Key, Record, TableInfo, TableVisitor}};\n\
             {}\ntables! {{\n",
            use_line("crate::model", &models)
        );
        for (table, name) in rows {
            writeln!(code, "    {table}: {name},")?;
        }
        code.push_str("}\n");
        Ok(code)
    }
}

/// The Rust type of a record's `_key`.
fn key_type(name: &str, s: &StructSettings, field: &Field) -> anyhow::Result<String> {
    match (&s.key, &field.shape) {
        (Some(key), _) => Ok(key.clone()),
        (None, Shape::Integer) => Ok("u32".to_owned()),
        (None, _) => bail!("set the `key` of `{name}`: its keys are not numbers"),
    }
}

/// A `use` line for `names` from `path`, or nothing if there are none.
fn use_line(path: &str, names: &[&str]) -> String {
    match names {
        [] => String::new(),
        [name] => format!("use {path}::{name};\n"),
        names => format!("use {path}::{{{}}};\n", names.join(", ")),
    }
}

/// The names in a Rust type, such as `Vec` and `TypeId` in `Vec<TypeId>`.
fn type_names(ty: &str) -> impl Iterator<Item = &str> {
    ty.split(|c: char| !(c.is_ascii_alphanumeric() || c == '_'))
        .filter(|name| !name.is_empty())
}

/// The settings of a field, or the defaults.
fn field_settings<'s>(settings: &'s Settings, name: &str, json: &str) -> &'s FieldSettings {
    static NONE: FieldSettings = FieldSettings {
        name: None,
        ty: None,
        key: None,
        optional: false,
        default: false,
        raw: None,
        missing: None,
        doc: None,
    };
    settings
        .structs
        .get(name)
        .and_then(|s| s.fields.get(json))
        .unwrap_or(&NONE)
}

/// Add the fields that the settings keep although no record has them.
fn add_missing_fields(
    settings: &Settings,
    shapes: &mut BTreeMap<&str, BTreeMap<String, Field>>,
) -> anyhow::Result<()> {
    for (name, fields) in shapes.iter_mut() {
        let Some(s) = settings.structs.get(*name) else {
            continue;
        };
        for (json, fs) in &s.fields {
            let Some(shape) = &fs.missing else {
                continue;
            };
            if fields.contains_key(json) {
                bail!("`{name}.{json}` is in the schema again; remove its `missing`");
            }
            if matches!(shape, Shape::Array(_) | Shape::Object(_) | Shape::Unknown) {
                bail!("`missing` of `{name}.{json}` must be a number, flag, string or text");
            }
            let field = Field {
                required: false,
                shape: shape.clone(),
            };
            fields.insert(json.clone(), field);
        }
    }
    Ok(())
}

/// The fields of the object a field holds, if it holds one in a struct of
/// its own: directly, as list items, or as the values of a map.
fn object_of<'s>(shape: &'s Shape, fs: &FieldSettings) -> Option<&'s BTreeMap<String, Field>> {
    if fs.raw.is_some() {
        return None;
    }
    match shape {
        Shape::Object(fields) => Some(fields),
        Shape::Array(item) => match item.as_ref() {
            Shape::Object(fields) if is_map(fields) => match &fields["_value"].shape {
                Shape::Object(value) => Some(value),
                Shape::Array(inner) => match inner.as_ref() {
                    Shape::Object(value) => Some(value),
                    _ => None,
                },
                _ => None,
            },
            Shape::Object(fields) if is_keyed_text(fields) => None,
            Shape::Object(fields) => Some(fields),
            _ => None,
        },
        _ => None,
    }
}

/// The struct that a field's objects go into.
fn struct_name(name: &str, json: &str, fs: &FieldSettings) -> anyhow::Result<String> {
    fs.ty
        .clone()
        .with_context(|| format!("set the `type` of `{name}.{json}` to the struct that holds it"))
}

/// A list of `{"_key": …, "_value": …}`: how CCP writes a map with integer
/// keys.
fn is_map(fields: &BTreeMap<String, Field>) -> bool {
    fields.len() == 2 && fields.contains_key("_key") && fields.contains_key("_value")
}

/// A list of `{"_key": …, "en": …, "de": …}`: text by key.
fn is_keyed_text(fields: &BTreeMap<String, Field>) -> bool {
    fields.contains_key("_key")
        && fields.contains_key("en")
        && fields
            .keys()
            .all(|key| key == "_key" || LANGUAGES.contains(&key.as_str()))
}

fn option(required: bool, ty: &str) -> String {
    if required {
        ty.to_owned()
    } else {
        format!("Option<{ty}>")
    }
}

/// Merge the fields of another place a struct is used. A field that one
/// place lacks is not required.
fn merge_fields(
    into: &mut BTreeMap<String, Field>,
    from: &BTreeMap<String, Field>,
) -> anyhow::Result<()> {
    for (json, field) in into.iter_mut() {
        if !from.contains_key(json) {
            field.required = false;
        }
    }
    for (json, field) in from {
        match into.get_mut(json) {
            Some(existing) => {
                existing.required &= field.required;
                existing.shape = merge_shape(&existing.shape, &field.shape)
                    .with_context(|| format!("field `{json}`"))?;
            }
            None => {
                into.insert(
                    json.clone(),
                    Field {
                        required: false,
                        shape: field.shape.clone(),
                    },
                );
            }
        }
    }
    Ok(())
}

fn merge_shape(a: &Shape, b: &Shape) -> anyhow::Result<Shape> {
    Ok(match (a, b) {
        _ if a == b => a.clone(),
        (Shape::Integer, Shape::Float) | (Shape::Float, Shape::Integer) => Shape::Float,
        (Shape::Unknown, other) | (other, Shape::Unknown) => other.clone(),
        (Shape::Array(x), Shape::Array(y)) => Shape::Array(Box::new(merge_shape(x, y)?)),
        (Shape::Object(x), Shape::Object(y)) => {
            let mut fields = x.clone();
            merge_fields(&mut fields, y)?;
            Shape::Object(fields)
        }
        _ => bail!("the places it is used hold different kinds of value"),
    })
}

/// `typeID` → `type_id`, `allowCCPDevs` → `allow_ccp_devs`.
///
/// Both stores name the tables of files without a model by the same rule
/// (`table_name` in `src/tables.rs`). Keep the two the same, so that a file
/// keeps its name in a store once it has a model. `xtask` does not depend on
/// `eve-sde`, because `eve-sde` could then not be fixed by regenerating its
/// models, so the rule is written twice and both copies carry these tests.
fn snake_case(name: &str) -> String {
    let name = name.replace("IDs", "Ids").replace("ID", "Id");
    let chars: Vec<char> = name.chars().collect();
    let mut out = String::new();
    for (i, &c) in chars.iter().enumerate() {
        if !c.is_ascii_uppercase() {
            out.push(c);
            continue;
        }
        let prev = i.checked_sub(1).and_then(|j| chars.get(j));
        let next = chars.get(i + 1);
        let after_lowercase = prev.is_some_and(char::is_ascii_lowercase);
        let ends_acronym = prev.is_some_and(char::is_ascii_uppercase)
            && next.is_some_and(char::is_ascii_lowercase);
        if after_lowercase || ends_acronym {
            out.push('_');
        }
        out.push(c.to_ascii_lowercase());
    }
    out
}

/// Write a doc comment, one `prefix` line for each line of `doc`.
fn push_doc(code: &mut String, doc: Option<&str>, prefix: &str, indent: &str) {
    let Some(doc) = doc else {
        return;
    };
    for line in doc.trim_end().lines() {
        code.push_str(indent);
        code.push_str(prefix);
        if !line.is_empty() {
            code.push(' ');
            code.push_str(line);
        }
        code.push('\n');
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn shape(json: &str) -> Shape {
        serde_json::from_str(json).unwrap()
    }

    fn tables(record: &str) -> Tables {
        Tables::from([(
            "things".to_owned(),
            schema::Table {
                file: "things.jsonl".to_owned(),
                record: shape(record),
            },
        )])
    }

    fn settings(text: &str) -> Settings {
        toml::from_str(text).unwrap()
    }

    const RECORD: &str = r#"{"object": {
        "_key": {"required": true, "type": "integer"},
        "name": {"required": true, "type": "text"},
        "note": {"required": false, "type": "text"},
        "groupID": {"required": true, "type": "integer"},
        "mass": {"required": false, "type": "float"},
        "stargateIDs": {"required": true, "type": {"array": "integer"}},
        "position2D": {"required": true, "type": {"object": {
            "x": {"required": true, "type": "float"}}}},
        "skills": {"required": false, "type": {"array": {"object": {
            "_key": {"required": true, "type": "integer"},
            "_value": {"required": true, "type": "integer"}}}}},
        "parts": {"required": true, "type": {"array": {"object": {
            "_key": {"required": true, "type": "integer"},
            "count": {"required": true, "type": "integer"}}}}},
        "blob": {"required": true, "type": {"object": {
            "a": {"required": true, "type": "bool"}}}}
    }}"#;

    const SETTINGS: &str = r#"
        [ids]
        groupID = "GroupId"

        [modules.things]
        doc = "Things."

        [structs.Thing]
        module = "things"
        file = "things.jsonl"
        key = "TypeId"
        doc = "`things.jsonl`"

        [structs.Thing.fields.stargateIDs]
        type = "StargateId"

        [structs.Thing.fields.position2D]
        name = "position_2d"
        type = "Position2D"

        [structs.Thing.fields.skills]
        key = "TypeId"
        type = "u8"

        [structs.Thing.fields.parts]
        type = "Part"

        [structs.Thing.fields.blob]
        raw = "value"

        [structs.Position2D]
        module = "shapes"
        derive = ["Copy"]
        doc = "A point on the 2D map."

        [structs.Part]
        module = "things"
        derive = ["Eq"]

        [structs.Part.fields._key]
        name = "type_id"
        type = "TypeId"
        doc = "The part's type."
    "#;

    #[test]
    fn generates_a_module_and_the_table_list() {
        let files = generate(&tables(RECORD), &settings(SETTINGS)).unwrap();
        insta::assert_snapshot!("things", files["src/model/things.rs"]);
        insta::assert_snapshot!("shapes", files["src/model/shapes.rs"]);
        insta::assert_snapshot!("list", files["src/tables/list.rs"]);
    }

    #[test]
    fn a_nested_object_needs_a_struct_name() {
        let mut s = settings(SETTINGS);
        s.structs.get_mut("Thing").unwrap().fields.remove("parts");
        s.structs.remove("Part");
        let err = generate(&tables(RECORD), &s).unwrap_err();
        assert_eq!(
            err.to_string(),
            "set the `type` of `Thing.parts` to the struct that holds it"
        );
    }

    #[test]
    fn settings_for_a_field_the_schema_lacks_are_an_error() {
        let text = format!("{SETTINGS}\n[structs.Thing.fields.gone]\ntype = \"u32\"\n");
        let err = generate(&tables(RECORD), &settings(&text)).unwrap_err();
        assert_eq!(
            err.to_string(),
            "the settings name `Thing.gone`, which the schema does not have"
        );
    }

    #[test]
    fn a_struct_nothing_holds_is_an_error() {
        let text = format!("{SETTINGS}\n[structs.Spare]\nmodule = \"things\"\n");
        let err = generate(&tables(RECORD), &settings(&text)).unwrap_err();
        assert_eq!(
            err.to_string(),
            "`Spare` is declared in the settings, but no field holds it"
        );
    }

    #[test]
    fn a_table_without_a_struct_is_an_error() {
        let err = generate(&tables(RECORD), &Settings::default()).unwrap_err();
        assert_eq!(
            err.to_string(),
            "these tables have no struct in the settings: things"
        );
    }

    #[test]
    fn a_field_no_record_has_can_be_kept() {
        let text = format!("{SETTINGS}\n[structs.Part.fields.cost]\nmissing = \"float\"\n");
        let files = generate(&tables(RECORD), &settings(&text)).unwrap();
        assert!(files["src/model/things.rs"].contains("pub cost: Option<f64>,"));
    }

    #[test]
    fn json_names_become_snake_case() {
        assert_eq!(snake_case("typeID"), "type_id");
        assert_eq!(snake_case("includedTypeIDs"), "included_type_ids");
        assert_eq!(snake_case("allowCCPDevs"), "allow_ccp_devs");
        assert_eq!(snake_case("iconSmallNPC"), "icon_small_npc");
        assert_eq!(snake_case("showOutputValueInUI"), "show_output_value_in_ui");
        assert_eq!(
            snake_case("linkEffectGraphicIDOverride"),
            "link_effect_graphic_id_override"
        );
        assert_eq!(snake_case("fuel_type_id"), "fuel_type_id");
        assert_eq!(snake_case("heightMap1"), "height_map1");
    }

    #[test]
    fn places_that_disagree_make_a_field_optional() {
        let mut a = BTreeMap::from([(
            "x".to_owned(),
            Field {
                required: true,
                shape: Shape::Integer,
            },
        )]);
        let b = BTreeMap::from([
            (
                "x".to_owned(),
                Field {
                    required: true,
                    shape: Shape::Float,
                },
            ),
            (
                "y".to_owned(),
                Field {
                    required: true,
                    shape: Shape::Bool,
                },
            ),
        ]);
        merge_fields(&mut a, &b).unwrap();
        assert_eq!(a["x"].shape, Shape::Float);
        assert!(a["x"].required);
        assert!(!a["y"].required);
    }
}
